const systems={Cardiovascular:['Hypertension','Coronary Artery Disease','Angina Pectoris','Myocardial Infarction','Heart Failure','Cardiac Dysrhythmias','Pericarditis','Peripheral Arterial Disease','Deep Vein Thrombosis','Valvular Heart Diseases','Myocarditis','Cardiomyopathies','Cardiac Assessment & Diagnostics','Chronic Venous Insufficiency'],Respiratory:['Asthma','COPD','Pneumonia','Tuberculosis','Pulmonary Embolism','Pneumothorax','Pleural Effusion','Acute Respiratory Failure','ARDS','Bronchiectasis','Pulmonary Hypertension','Respiratory Assessment & Diagnostics','Oxygen Therapy & Airway Management','Mechanical Ventilation','Chest Tubes & Pleural Drainage','Lung Cancer','Interstitial Lung Diseases','Empyema','Sleep Apnea','Aspiration & Airway Obstruction','Tracheostomy Care','Thoracentesis'],Gastrointestinal:['GERD','Gastritis','Peptic Ulcer Disease','Upper & Lower GI Bleeding','Appendicitis','Peritonitis','Intestinal Obstruction','Irritable Bowel Syndrome','Inflammatory Bowel Disease','Acute & Chronic Pancreatitis','Hepatitis','Liver Cirrhosis','Hepatic Encephalopathy','Cholelithiasis & Cholecystitis','Colorectal Cancer','Esophageal & Gastric Cancer','GI Assessment & Diagnostic Procedures','Enteral & Parenteral Nutrition','Hemorrhoids & Anal Fissures','Esophageal Varices','Ascites & Spontaneous Bacterial Peritonitis','Acute Liver Failure','Gallstone Pancreatitis & Cholangitis','Dysphagia & Aspiration Precautions'],Endocrine:['Type 1 Diabetes Mellitus','Type 2 Diabetes Mellitus','Diabetic Ketoacidosis','Hyperosmolar Hyperglycemic State','Hypoglycemia','Hypothyroidism','Hyperthyroidism','Thyroid Storm','Goiter & Thyroid Nodules','Thyroid Cancer','Addison Disease','Cushing Syndrome','Adrenal Crisis','SIADH','Diabetes Insipidus','Hyperparathyroidism','Hypoparathyroidism','Pituitary Disorders','Endocrine Assessment & Diagnostics','Insulin Therapy & Diabetes Education','Graves Disease','Hashimoto Thyroiditis','Acromegaly & Gigantism','Pheochromocytoma','Primary Hyperaldosteronism','Metabolic Syndrome','Diabetic Foot & Chronic Complications','Thyroidectomy & Postoperative Care','Adrenalectomy & Postoperative Care'], 'Renal & Urinary':['Acute Kidney Injury','Chronic Kidney Disease','End-Stage Kidney Disease','Hemodialysis','Peritoneal Dialysis','Urinary Tract Infection','Pyelonephritis','Glomerulonephritis','Nephrotic Syndrome','Nephrolithiasis','Urinary Retention','Urinary Incontinence','Hydronephrosis','Benign Prostatic Hyperplasia','Bladder Cancer','Prostate Cancer','Renal Cell Carcinoma','Acid–Base & Electrolyte Imbalances','Urinary Catheterization & Catheter Care','Kidney Transplantation','Renal Assessment & Diagnostics','Acute Nephritic Syndrome','Renal Artery Stenosis','Neurogenic Bladder','Continuous Renal Replacement Therapy']};
const names=['Definition & Overview','Etiology & Risk Factors','Pathophysiology','Signs & Symptoms','Diagnostics','Medical Management','Nursing Assessment & Interventions','Patient Education','Complications','Clinical Priorities','NANDA-I Nursing Diagnoses & Care Plans'];
const T=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const B=(s)=>`<div class="callout">${s}</div>`;
const sections=[
`<p><strong>Myocardial infarction (MI)</strong> is myocardial cell death due to prolonged ischemia. An acute MI requires acute myocardial injury (a rise/fall in cardiac troponin, with at least one value above the assay-specific 99th percentile) plus clinical evidence of acute myocardial ischemia.</p>${T(['Presentation','Distinguishing feature'],[['Unstable angina','Ischemia without troponin-defined infarction'],['NSTEMI','Acute MI without persistent diagnostic ST elevation'],['STEMI','Acute MI with diagnostic ST elevation or a recognized equivalent; requires urgent reperfusion pathway']])}<p><strong>Type 1 MI:</strong> typically acute coronary atherothrombosis. <strong>Type 2 MI:</strong> oxygen supply–demand mismatch without acute atherothrombosis.</p>${B('<strong>Clinical pearl:</strong> Elevated troponin alone indicates myocardial injury, not necessarily myocardial infarction. A normal initial ECG or troponin cannot rule out evolving ACS.')}`,
`<p>Most Type 1 MIs follow plaque rupture or erosion, platelet activation, and coronary thrombosis. Other mechanisms include coronary vasospasm, embolism, spontaneous coronary artery dissection, and supply–demand imbalance.</p><h3>Modifiable risk factors</h3><ul><li>Hypertension, dyslipidemia, smoking, diabetes, inactivity, excess adiposity</li><li>Unhealthy dietary patterns and certain stimulant exposures</li></ul><h3>Other risk factors</h3><ul><li>Older age, family history of premature coronary disease, inherited lipid disorders</li></ul>${B('Absence of classic risk factors does not exclude acute MI.')}`,
`<p>In plaque-related MI, a coronary thrombus reduces blood flow. Myocardial oxygen delivery falls, impairing cellular metabolism, contractility, and electrical stability. Persistent ischemia may lead to irreversible cell injury and necrosis.</p><div class="mini" style="text-align:center">Plaque disruption ↓<br>Thrombus formation ↓<br>Reduced coronary perfusion ↓<br>Myocardial ischemia ↓<br>Electrical instability and impaired contractility ↓<br>Myocardial necrosis if prolonged</div><p>Infarct location affects complications. Right ventricular involvement can produce hypotension, elevated jugular venous pressure, and relatively clear lungs.</p>` ,
`<h3>Common findings</h3><ul><li>Chest pressure, heaviness, tightness, or discomfort radiating to arm, neck, jaw, back, or epigastrium</li><li>Dyspnea, diaphoresis, nausea, vomiting, fatigue, lightheadedness</li><li>Pallor, cool skin, tachycardia or bradycardia, anxiety or distress</li></ul><h3>Less typical presentations</h3><p>Some patients, including older adults and people with diabetes, may experience dyspnea, fatigue, nausea, or weakness without prominent chest pain.</p>${B('<strong>Escalate immediately:</strong> hypotension, altered mental status, syncope, severe dyspnea, pulmonary edema, unstable rhythm, or persistent ischemic symptoms.')}`,
`${T(['Investigation','Nursing relevance'],[['12-lead ECG','Obtain and interpret promptly, aiming within 10 minutes of first medical contact/presentation per pathway'],['Serial high-sensitivity troponin','Assess rise/fall using the local validated assay and protocol'],['Echocardiography','Assess ventricular function, wall motion, and complications'],['Coronary angiography','Identify coronary anatomy and support revascularization'],['CBC, electrolytes, kidney function','Assess anemia, electrolyte disturbance, and treatment risks']])}<h3>ECG territories</h3>${T(['Leads','Common territory'],[['II, III, aVF','Inferior'],['V1–V4','Septal/anterior'],['I, aVL, V5–V6','Lateral']])}${B('Do not wait for troponin confirmation before activating an indicated STEMI reperfusion pathway. Repeat ECGs if symptoms evolve or the initial tracing is nondiagnostic.')}`,
`<p>Acute management depends on the ECG, symptoms, stability, bleeding risk, contraindications, and local protocol. Early assessment, monitoring, vascular access, indicated antithrombotic therapy, and reperfusion are priorities.</p><h3>Reperfusion</h3><p>Primary PCI is preferred for STEMI when timely. Selected patients with STEMI presenting early and an anticipated PCI delay may be candidates for fibrinolysis if no contraindications exist. Fibrinolysis is not routine NSTEMI treatment.</p>${T(['Treatment','Key nursing check'],[['Aspirin / P2Y12 inhibitor','Allergy, active bleeding, adherence, procedure plan'],['Anticoagulants','Bleeding, renal function, drug-specific monitoring'],['Nitroglycerin','BP, recent PDE-5 inhibitors, possible RV infarction'],['Beta-blockers','HR, BP, AV block, acute decompensated heart failure'],['High-intensity statin','Adverse effects, interactions, adherence'],['ACE inhibitor / ARB when indicated','BP, kidney function, potassium']])}${B('Supplemental oxygen is indicated for hypoxemia (e.g., SpO₂ < 90%). Routine oxygen is not recommended solely for ACS when SpO₂ is ≥ 90%.')}`,
`${T(['Assessment cue','Nursing action','Rationale'],[['New ischemic discomfort','Assess ABCs, vital signs, obtain ECG, escalate','Recognize time-critical ACS'],['Nondiagnostic first ECG with ongoing symptoms','Repeat ECG and serial troponin per protocol','Early ischemia may not be evident initially'],['SpO₂ < 90%','Give oxygen per protocol and reassess','Correct hypoxemia'],['Inferior STEMI with hypotension','Consider RV involvement; check right-sided leads and nitrate safety','RV infarction may be preload-sensitive'],['Unstable sustained ventricular tachycardia','Activate emergency response and follow ACLS','Prevent arrest'],['Hypotension, confusion, oliguria, crackles','Escalate possible cardiogenic shock','Detect inadequate perfusion'],['Bleeding after PCI','Assess access site, circulation, hemodynamics','Identify vascular complications']])}<h3>Focused assessment</h3><p>Record onset, location, radiation, severity, associated symptoms, medication exposure, allergies, previous cardiac history, BP, pulse, oxygenation, perfusion, rhythm, and response to therapy.</p>${B('Nursing care plans never delay emergency reperfusion or stabilization.')}`,
`<ul><li>Explain prescribed medications, particularly the importance of not independently stopping antiplatelet therapy after stenting.</li><li>Promote smoking cessation, heart-healthy eating, individualized activity, and control of BP, diabetes, and cholesterol.</li><li>Encourage cardiac rehabilitation, follow-up, and recommended monitoring.</li><li>Teach recognition of recurrent chest discomfort, severe breathlessness, syncope, and stroke symptoms; activate emergency medical services.</li><li>Use teach-back to verify understanding and explore access or adherence barriers.</li></ul>${B('Pain relief does not independently establish that ischemia has resolved.')}`,
`${T(['Complication','Clinical cues'],[['Ventricular tachycardia/fibrillation','Unstable rhythm, syncope, cardiac arrest'],['Acute heart failure','Dyspnea, crackles, hypoxemia'],['Cardiogenic shock','Hypotension with impaired tissue perfusion'],['Papillary muscle rupture','Acute severe mitral regurgitation, pulmonary edema'],['Ventricular septal rupture','New murmur, shock'],['Free-wall rupture','Sudden collapse, possible tamponade'],['Pericarditis','Pleuritic or positional pain'],['LV thrombus','Systemic embolic risk']])}${B('Sudden deterioration after MI requires urgent reassessment, including consideration of mechanical complications.')}`,
`<ul><li>Recognize ACS from symptoms, ECG, and serial troponin patterns.</li><li>Obtain a prompt ECG; do not wait for biomarkers when STEMI is evident.</li><li>Elevated troponin does not always mean Type 1 MI.</li><li>Routine oxygen is not indicated in normoxemic ACS.</li><li>Check nitrate contraindications, especially hypotension and suspected RV infarction.</li><li>Prioritize unstable rhythm, shock, and respiratory failure over routine education.</li><li>Base delegation on patient stability and local scope-of-practice rules.</li></ul>` ,
`<p><strong>NANDA-I diagnoses must be selected from patient-specific assessment findings.</strong> The following are educational candidate care plans. Exact official labels, defining characteristics, related factors, NOC and NIC terminology/codes require verification against licensed current editions before publication.</p><h3>Illustrative case: Acute anterior STEMI</h3><p>61-year-old patient, chest pressure 9/10 for 50 minutes, diaphoresis, HR 108, BP 152/92, RR 24, SpO₂ 94% on room air, ST elevation V2–V4.</p>${T(['Candidate diagnosis','Assessment support','Status'],[['Acute Pain','Reported chest pressure 9/10, visible distress','Supported'],['Anxiety','Requires patient-reported fear or other defining cues','Assess further'],['Decreased Cardiac Output','Requires evidence of impaired cardiac output/perfusion','Not established'],['Ineffective Health Self-Management','Requires evidence of self-management difficulty','Assess during recovery']])}<h3>Care Plan: Acute Pain</h3><p><strong>Provisional PES:</strong> Acute Pain related to a physiological injury process as evidenced by severe chest pressure rated 9/10 and visible distress.</p><p><strong>Expected outcomes:</strong> Reports improved discomfort after treatment; promptly reports recurrence; remains closely monitored during reperfusion.</p>${T(['Nursing intervention','Rationale'],[['Assess pain quality, onset, radiation, severity, and associated symptoms','Establish baseline and identify change'],['Facilitate immediate ECG and STEMI pathway','Reduce time to indicated reperfusion'],['Give ordered treatment after safety checks','Support treatment while preventing harm'],['Reassess pain, BP, rhythm, and perfusion','Detect deterioration and evaluate response']])}<p><strong>Evaluation:</strong> Document symptom trends and objective clinical status; absence of pain alone does not prove reperfusion.</p><h3>Additional candidate care plans</h3><p><strong>Anxiety:</strong> Assess patient-reported fear; offer brief explanations and supportive communication without delaying care. <strong>Decreased Cardiac Output:</strong> If impaired perfusion is established, monitor BP, mentation, urine output, pulmonary findings, and escalate suspected shock. <strong>Health self-management:</strong> If barriers are identified, use teach-back, collaborative goals, and cardiac rehabilitation referrals.</p>${B('PES format applies to appropriate problem-focused diagnoses. Risk diagnoses follow a different structure and should not be assigned invented symptoms.')}`
];
// Additional exam-focused teaching material. Clinical editorial review required before publication.
const extendedReview=[
`<h3>Learning objectives</h3><ul><li>Differentiate myocardial injury, Type 1 MI, Type 2 MI, STEMI and NSTEMI.</li><li>Connect assessment findings to immediate nursing priorities.</li><li>Identify clinical deterioration and evaluate treatment response.</li></ul><h3>Important distinctions</h3>${T(['Concept','Meaning'],[['Myocardial injury','Troponin above the assay-specific 99th percentile; acute when values rise or fall'],['Myocardial infarction','Acute myocardial injury plus evidence of ischemia'],['Unstable angina','Ischemic syndrome without biomarker-defined myocardial necrosis']])}`,
`<h3>Clinical assessment of risk</h3><p>Ask about hypertension, diabetes, lipid disorders, tobacco exposure, premature coronary disease in relatives, medication adherence, and previous coronary interventions. Consider nonatherosclerotic causes when the presentation suggests them.</p>${B('A patient may develop MI without chest pain or without previously known coronary disease.')}`,
`<h3>Mechanism-to-symptom connections</h3>${T(['Mechanism','Possible finding'],[['Sympathetic activation','Diaphoresis, pallor, tachycardia'],['Loss of ventricular contractility','Reduced cardiac output, pulmonary congestion'],['Ischemic electrical instability','Ventricular arrhythmias or conduction blocks'],['Inferior/RV involvement','Bradycardia, hypotension, elevated JVP']])}<p>Clinical patterns are clues, not definitive proof of a particular infarct location or complication.</p>`,
`<h3>Focused history using OPQRST</h3><ul><li><strong>O:</strong> Onset and circumstances.</li><li><strong>P:</strong> Provoking or relieving factors.</li><li><strong>Q:</strong> Quality of discomfort.</li><li><strong>R:</strong> Region and radiation.</li><li><strong>S:</strong> Severity and associated symptoms.</li><li><strong>T:</strong> Timing, duration and recurrence.</li></ul><p>Record dyspnea, syncope, diaphoresis, nausea, and signs of impaired perfusion. Do not use symptom quality alone to rule out ACS.</p>`,
`<h3>Serial assessment</h3><p>Interpret ECG findings with symptoms, previous tracings, and serial troponin results. A single normal ECG or early troponin does not reliably exclude ACS. Follow locally validated rapid rule-out/rule-in protocols.</p><h3>Additional ECG considerations</h3><ul><li>Posterior infarction may require posterior leads.</li><li>Inferior MI with hypotension may warrant right-sided leads to assess RV involvement.</li><li>New or evolving ischemic changes require prompt escalation.</li></ul>`,
`<h3>Reperfusion and monitoring pathway</h3><ol><li>Identify suspected ACS and assess immediate stability.</li><li>Obtain rapid ECG and activate the appropriate pathway.</li><li>Assess allergies, bleeding risk, hemodynamics, and medication contraindications.</li><li>Prepare for indicated coronary angiography/PCI; assess fibrinolysis eligibility only where relevant to STEMI and protocol.</li><li>Monitor rhythm, symptoms, bleeding, and signs of reperfusion or complications.</li></ol><h3>Safety reminders</h3><p>Nitrates can worsen hypotension and are generally avoided in suspected RV infarction. Beta-blockers require caution in shock, significant bradycardia or conduction disease. Antithrombotic choices depend on the treatment strategy and bleeding risk.</p>`,
`<h3>Before, during and after PCI</h3>${T(['Phase','Nursing responsibilities'],[['Before','Verify identity, allergies, ordered labs, consent process and time-critical handoff'],['During','Monitor symptoms, rhythm and hemodynamics; communicate acute changes'],['After','Check access-site bleeding, distal circulation, rhythm, pain, BP and prescribed activity restrictions']])}<h3>Evaluation checklist</h3><ul><li>Has discomfort improved, persisted or returned?</li><li>Are perfusion, mental status, rhythm and oxygenation stable?</li><li>Are there new crackles, hypotension, bleeding or vascular changes?</li><li>Was a concerning change escalated and documented promptly?</li></ul>`,
`<h3>Discharge teach-back</h3><p>Ask the patient to explain why each medication is prescribed, what to do if symptoms recur, and how follow-up and cardiac rehabilitation will work. Identify cost, language, transport, or health-literacy barriers before discharge.</p><h3>Example teach-back prompts</h3><ul><li>“What will you do if chest pressure returns?”</li><li>“What is your plan for taking antiplatelet medicines?”</li><li>“When is your follow-up appointment?”</li></ul>`,
`<h3>Recognize deterioration</h3>${T(['New cue','Priority consideration'],[['Sustained unstable ventricular rhythm','Emergency rhythm management per ACLS'],['Hypotension, oliguria, confusion','Possible cardiogenic shock'],['Sudden pulmonary edema or new murmur','Acute valve or septal mechanical complication'],['Sudden collapse after MI','Life-threatening arrhythmia or structural complication']])}<p>Mechanical complications require urgent specialist evaluation; bedside echo may help identify the cause.</p>`,
`<h3>Clinical judgment sequence</h3><ol><li><strong>Recognize cues:</strong> symptoms, ECG, hemodynamics and troponin trend.</li><li><strong>Analyze cues:</strong> ischemia versus other dangerous causes; stable versus unstable.</li><li><strong>Prioritize:</strong> immediate threats to airway, circulation and myocardial perfusion.</li><li><strong>Act:</strong> escalate, monitor, administer prescribed therapy safely and prepare for reperfusion.</li><li><strong>Evaluate:</strong> symptom trend, rhythm, BP, perfusion and complications.</li></ol>`,
`<h3>Care-plan selection exercise</h3>${T(['Finding','Reasoning'],[['Chest pain 9/10 and distress','Acute Pain is supported by current cues'],['Patient verbally reports intense fear','Assess Anxiety using the required defining characteristics'],['Confusion, oliguria and hypotension','Evaluate for low cardiac output and shock; urgent escalation first'],['Missed medications and difficulty following regimen','Assess whether a self-management diagnosis is supported']])}<h3>Documentation template</h3><p><strong>Assessment cues → Nursing diagnosis → Patient-specific outcome → Intervention + rationale → Reassessment/evaluation.</strong> Use verified NANDA-I, NIC and NOC labels only when the licensed taxonomy has been checked. Do not invent official codes.</p>`
];
for(let i=0;i<sections.length;i++)sections[i]+=extendedReview[i];
const questions=[{q:'A patient with suspected MI arrives with ongoing chest pressure. What is the priority initial diagnostic action?',options:['Wait for the first troponin result','Obtain a 12-lead ECG promptly','Arrange a routine stress test','Begin discharge teaching'],correct:1,why:['Troponin is important but must not delay ECG.','Correct: prompt ECG can identify time-critical STEMI.','A routine stress test is not an initial emergency action.','Education comes after acute stabilization.']},{q:'An inferior STEMI patient has BP 86/54 mmHg, HR 52/min, elevated JVP, and clear lungs. What is the safest priority?',options:['Give nitroglycerin immediately','Activate STEMI response and evaluate right ventricular involvement','Give high-flow oxygen regardless of saturation','Wait for serial troponins before escalation'],correct:1,why:['Nitroglycerin may worsen hypotension, particularly with RV involvement.','Correct: urgent reperfusion and RV assessment are priorities.','Routine oxygen is not indicated without hypoxemia.','STEMI care must not wait for troponin.']},{q:'Which nursing diagnosis is best supported by chest pain rated 9/10 and visible distress, without evidence of poor perfusion?',options:['Decreased Cardiac Output','Acute Pain','Ineffective Health Self-Management','Impaired Gas Exchange'],correct:1,why:['No clear low-output evidence has been provided.','Correct: pain is directly supported by patient report.','Self-management barriers have not been assessed.','No gas exchange impairment is established.']},{q:'A post-MI patient becomes confused, hypotensive, oliguric, and develops crackles. What should the nurse do first?',options:['Continue routine discharge education','Escalate immediately for suspected cardiogenic shock','Administer an unassessed large fluid bolus','Assume symptoms are normal after MI'],correct:1,why:['The patient is unstable and needs urgent assessment.','Correct: findings suggest impaired perfusion and possible pump failure.','Fluids require individualized assessment, especially with pulmonary congestion.','This is not an expected stable recovery pattern.']}];
const cases=[{title:'Case 1 — Acute Inferior STEMI',level:'Solved case',body:'A 58-year-old patient has 45 minutes of crushing chest pressure, diaphoresis, nausea, BP 148/88, HR 96, SpO₂ 96% on room air, and ST elevation in II, III, aVF.',answer:'Activate the STEMI pathway, monitor continuously, check medication safety, and prepare for urgent reperfusion. Assess for right ventricular involvement if hypotension or suggestive signs develop. Do not give routine oxygen solely for an SpO₂ of 96%.',why:'Compatible symptoms and inferior ST elevation indicate a time-sensitive reperfusion pathway. Troponin confirmation must not delay indicated emergency action.'},{title:'Case 2 — Cardiogenic Shock',level:'Solved case',body:'Several hours after an extensive anterior MI, a 67-year-old develops dyspnea and confusion, BP 78/48, HR 124, SpO₂ 88%, urine output 15 mL/hour, and bilateral crackles.',answer:'Suspect cardiogenic shock with acute left ventricular failure. Activate emergency escalation, support oxygenation, monitor perfusion and rhythm, and prepare for urgent hemodynamic evaluation and prescribed treatment.',why:'Hypotension, confusion, oliguria, and pulmonary congestion together suggest low cardiac output and impaired tissue perfusion. Avoid indiscriminate fluid boluses in pulmonary edema.'},{title:'Case 3 — RV Infarction Clinical Judgment',level:'Independent case',body:'A 64-year-old has chest pressure for 30 minutes, BP 86/54, HR 52, SpO₂ 95%, ST elevation in II, III, aVF, elevated JVP, and clear lungs.',answer:'Urgently activate the STEMI response, assess right ventricular involvement with right-sided ECG leads when indicated, and avoid nitrates pending evaluation.',why:'Inferior STEMI with hypotension, bradycardia, elevated JVP, and clear lungs suggests RV involvement. Nitrates may worsen hypotension.'}];
questions.push(
{q:'A patient with chest discomfort has an initial nondiagnostic ECG, but symptoms continue. Which response is most appropriate?',options:['Exclude ACS based on one ECG','Repeat ECG and continue serial assessment per protocol','Begin exercise testing immediately','Discharge without further evaluation'],correct:1,why:['One ECG does not exclude evolving ACS.','Correct: repeat ECG and serial troponin are appropriate when suspicion persists.','Exercise testing is not an immediate response to ongoing suspected ACS.','Ongoing concerning symptoms require evaluation.']},
{q:'Which finding after PCI requires the most urgent nursing escalation?',options:['Patient asks about diet','Small stable bruising documented at the access site','Expanding access-site hematoma with falling blood pressure','Patient wants a cardiac rehabilitation brochure'],correct:2,why:['Teaching is important after stabilization.','A stable small bruise needs monitoring but is less urgent.','Correct: expanding bleeding with hypotension can signal major vascular hemorrhage.','Education can wait until the patient is safe.']},
{q:'A patient with suspected MI has SpO₂ 97% on room air. What is the best oxygen-related action?',options:['Give high-flow oxygen routinely','Monitor oxygenation and administer oxygen if indicated by clinical status or protocol','Ignore respiratory assessment','Delay ECG until oxygen is started'],correct:1,why:['Routine oxygen in normoxemic ACS is not recommended.','Correct: assess continuously and treat hypoxemia when present.','Respiratory assessment remains essential.','ECG should not be delayed for unnecessary oxygen.']},
{q:'Which statement best distinguishes myocardial injury from MI?',options:['Any troponin elevation proves Type 1 MI','MI requires evidence of ischemia in addition to acute myocardial injury','MI is diagnosed only by chest pain','A normal initial troponin always excludes MI'],correct:1,why:['Troponin may rise for nonischemic reasons.','Correct: acute injury plus evidence of acute ischemia is required.','Symptoms alone are insufficient.','Early troponin may be normal before a rise.']}
);
const icons={'Cardiovascular':'♡','Respiratory':'◌','Gastrointestinal':'◈','Endocrine':'◇','Renal & Urinary':'⌁'};

// Heart Failure draft module: educational use; clinical/editorial review pending.
const hfNames=['Definition & Classification','Etiology & Risk Factors','Pathophysiology','Clinical Manifestations','Diagnostic Evaluation','Medical & Pharmacological Management','Nursing Assessment','Nursing Interventions & Rationales','Patient Education & Discharge','Complications & Clinical Priorities','Nursing Care Plans & Practice'];
const hfSections=[
`<p><strong>Heart failure (HF)</strong> is a clinical syndrome of symptoms and/or signs caused by structural or functional cardiac abnormalities, supported by evidence of congestion or elevated filling pressures.</p>${T(['Phenotype','LVEF'],[['HFrEF','≤40%'],['HFmrEF','41–49%'],['HFpEF','≥50%'],['HFimpEF','Previously ≤40%, now >40% with ≥10-point increase']])}<p>Distinguish chronic stable HF from acute decompensated HF. Ejection fraction is one descriptor; symptoms, volume status, perfusion and cause guide nursing priorities.</p>`,
`<p>Common causes include ischemic heart disease, chronic hypertension, valvular disease, cardiomyopathy, and arrhythmias. Precipitants of decompensation include infection, acute coronary syndrome, uncontrolled blood pressure, rapid atrial fibrillation, missed medications, excess sodium intake, renal dysfunction, and selected medications such as NSAIDs.</p>${B('<strong>Assessment cue:</strong> Ask what changed in the last several days: dyspnea, weight, medication use, diet, infection symptoms and urine output.')}`,
`<p>Reduced cardiac output and/or elevated filling pressures activate compensatory sympathetic and renin–angiotensin–aldosterone pathways. Persistent activation can increase afterload, sodium and water retention, congestion, and myocardial remodeling. Pulmonary congestion causes orthopnea and crackles; systemic venous congestion can cause edema, ascites and jugular venous distension.</p><p>Patients may have congestion without severe hypoperfusion, hypoperfusion without obvious edema, or both. Avoid assuming all edema is due to HF.</p>`,
`<p>Typical findings include exertional dyspnea, orthopnea, paroxysmal nocturnal dyspnea, fatigue, reduced exercise tolerance, peripheral edema, and rapid weight gain. Examination may reveal tachypnea, crackles, elevated JVP, an S3 gallop, cool extremities or altered mentation in poor perfusion.</p>${B('<strong>Red flags:</strong> Severe respiratory distress, new confusion, chest pain, marked hypotension, cyanosis or reduced urine output require urgent escalation.')}`,
`<p>Assess 12-lead ECG, natriuretic peptides (BNP or NT-proBNP when appropriate), renal function, electrolytes, CBC and troponin when ischemia is suspected. Echocardiography evaluates LVEF, chamber function and valve disease. Chest imaging may help identify congestion or alternative causes.</p>${T(['Test','Nursing interpretation'],[['BNP / NT-proBNP','Useful in diagnostic assessment; affected by age, renal dysfunction and obesity'],['Creatinine and potassium','Guide safety of diuretics and disease-modifying therapies'],['Echocardiogram','Characterizes EF and structural/valvular abnormalities'],['Pulse oximetry','Identify hypoxemia; normal oxygenation does not exclude HF']])}`,
`<p>In symptomatic chronic <strong>HFrEF</strong>, guideline-directed therapy commonly includes four foundational medication classes: an ARNI (or ACE inhibitor/ARB when appropriate), an evidence-based beta blocker, a mineralocorticoid receptor antagonist, and an SGLT2 inhibitor. Diuretics relieve congestion. Selection and titration require individualized blood pressure, kidney function and potassium monitoring.</p><p>For HFpEF/HFmrEF, SGLT2 inhibitors have important roles; manage congestion and comorbidities. In acute decompensation, treat the trigger and congestion, frequently with IV loop diuretics; oxygen is used for hypoxemia, not automatically for every patient.</p>${B('<strong>Safety:</strong> Do not initiate or up-titrate beta blockers during unstable shock; follow the treating team’s protocol.')}`,
`<p>Monitor respiratory effort, SpO₂, lung sounds, heart rate/rhythm, blood pressure, mentation, skin perfusion, edema, jugular venous pressure when trained, and activity tolerance. Trend daily weights under consistent conditions, intake/output, urine output, creatinine, sodium and potassium.</p><p>Review medication reconciliation, adherence barriers, diet, recent illness, and patient understanding. Escalate deteriorating perfusion or respiratory status promptly.</p>`,
`${T(['Intervention','Clinical rationale'],[['Position upright if dyspneic','May reduce work of breathing and improve comfort'],['Monitor weight and strict intake/output when ordered','Detects fluid balance trends and response to diuresis'],['Give prescribed diuretics; monitor urine output','Promotes decongestion while detecting poor response'],['Check renal function and electrolytes','Identifies treatment-related kidney injury and dyskalemia'],['Administer oxygen when hypoxemic per protocol','Corrects hypoxemia; routine oxygen is not indicated when saturation is adequate'],['Assess dizziness and orthostatic symptoms','Detects hypotension and fall risk during therapy'],['Use teach-back for medication and symptom plan','Confirms comprehension and supports self-management']])}<p>Reassess after interventions and communicate objective trends, not only isolated values.</p>`,
`<p>Teach the patient to take medicines as prescribed, attend follow-up, and weigh themselves daily under similar conditions if advised. Provide an individualized written action plan for worsening dyspnea, edema or rapid weight gain. Follow the clinician’s sodium and fluid guidance; fluid restriction is not universal for all patients.</p><p>Review medication side effects, blood pressure monitoring when relevant, activity progression, smoking cessation, vaccinations and when to seek emergency care. Confirm understanding with teach-back and address affordability and access.</p>`,
`<p>Major complications include acute pulmonary edema, cardiogenic shock, arrhythmias, worsening kidney function, thromboembolic events in selected patients, and recurrent hospitalization.</p>${T(['Priority presentation','Immediate nursing focus'],[['Acute pulmonary edema','Airway/breathing, upright position, rapid response, oxygen/ventilatory support as indicated'],['Hypotension with cool skin and confusion','Suspect hypoperfusion/shock; urgent escalation and hemodynamic monitoring'],['New chest pain or ischemic ECG changes','Activate acute coronary syndrome evaluation'],['Severe potassium abnormality','Cardiac monitoring and urgent prescriber notification']])}`,
`<p><strong>Care-plan examples</strong> below are clinical formulations; verify exact NANDA-I terminology and edition before formal academic submission.</p>${T(['Assessment cues','Candidate diagnosis / goal / interventions'],[['Crackles, orthopnea, edema, weight gain','Excess Fluid Volume (verify label): improve respiratory comfort and fluid balance; track weight, I/O, edema, response to diuretics'],['Fatigue and dyspnea on exertion','Activity Intolerance (verify label): tolerate graded activity with stable symptoms; pace care, monitor response, collaborate on rehabilitation'],['Difficulty explaining medication regimen','Deficient Knowledge / education need (verify label): demonstrate teach-back; provide simple written medication and symptom plan']])}<h3>Clinical mini-case</h3><p>A 72-year-old with HFrEF reports worsening orthopnea and a 2.5-kg weight increase over four days. RR 28/min, SpO₂ 89% on room air, bilateral crackles and leg edema. <strong>Priority:</strong> assess airway/breathing and perfusion, position upright, initiate oxygen per protocol for hypoxemia, notify the treating team promptly, and prepare prescribed decongestive therapy. Reassess oxygenation, respiratory effort, urine output, BP and electrolytes.</p><h3>NCLEX-style check</h3><p><strong>Question:</strong> Which finding after IV loop diuretic administration requires immediate follow-up?</p><p>A. Increased urine output &nbsp; B. Improved dyspnea &nbsp; C. New dizziness with BP 78/44 mmHg &nbsp; D. Reduced ankle swelling</p>${B('<strong>Answer: C.</strong> Severe symptomatic hypotension suggests impaired perfusion and requires urgent assessment and escalation. The other findings may indicate the intended decongestive response.')}`
];
function heartFailurePage(){return `<main class="shell"><div class="pagehead"><div class="crumb">Adult Health Nursing I / Cardiovascular / Draft Review</div><h1>Heart Failure (HF)</h1><p class="sub">11 clinical and nursing sections · No anatomy · Educational draft pending formal review</p></div><div class="layout"><aside class="sidebar"><h4>Heart Failure Sections</h4>${hfNames.map((n,i)=>`<button class="sidebtn ${state.hfSection===i?'active':''}" onclick="state.hfSection=${i};render();window.scrollTo({top:170,behavior:'smooth'})">${String(i+1).padStart(2,'0')} · ${n}</button>`).join('')}</aside><div class="content fade"><article class="panel"><div class="sectionbar"><span class="number">SECTION ${state.hfSection+1} / 11</span><span class="chip">Heart Failure</span></div><h2>${hfNames[state.hfSection]}</h2>${hfSections[state.hfSection]}</article><div class="actions" style="justify-content:space-between"><button class="btn secondary" ${state.hfSection===0?'disabled':''} onclick="state.hfSection--;render();window.scrollTo({top:170,behavior:'smooth'})">← Previous</button><button class="btn" ${state.hfSection===10?'disabled':''} onclick="state.hfSection++;render();window.scrollTo({top:170,behavior:'smooth'})">Next section →</button></div></div></div></main>`}

const state={hfSection:0,page:'home',system:'Cardiovascular',section:0,mode:'study',q:0,choice:null,submitted:false,case:0,caseReveal:false,caseChoice:null,search:'',term:false};
const storage=(key,def)=>{try{return JSON.parse(localStorage.getItem(key))??def}catch{return def}};let saved=storage('nursing-saved',false),done=storage('nursing-done',[]),scores=storage('nursing-scores',[]);
function persist(){localStorage.setItem('nursing-saved',JSON.stringify(saved));localStorage.setItem('nursing-done',JSON.stringify(done));localStorage.setItem('nursing-scores',JSON.stringify(scores))}
function go(page,extra){state.page=page;if(extra)Object.assign(state,extra);window.scrollTo({top:0,behavior:'smooth'});render()}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function header(){return `<header class="topbar"><div class="shell"><a class="brand" href="#" onclick="go('home');return false"><span class="logo">✚</span>Nursing <em>Atlas</em></a><nav class="nav"><button class="${state.page==='home'?'active':''}" onclick="go('home')">Home</button><button class="${state.page==='courses'?'active':''}" onclick="go('courses')">Courses</button><button class="${state.page==='topic'?'active':''}" onclick="go('topic')">MI Review</button><button class="${state.page==='practice'?'active':''}" onclick="go('practice')">Practice</button></nav><div class="right"><input aria-label="Search topics" class="search" id="search" placeholder="Search topics..." value="${escapeHtml(state.search)}" oninput="state.search=this.value;searchResults()" onkeydown="if(event.key==='Enter')go('search')"><button class="smallbtn" onclick="go('search')">⌕</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="shell"><strong>Nursing Atlas</strong> · Educational prototype · Content in English · Local progress only<br>Medical content is a draft pending formal editorial review. Not a substitute for clinical protocols or professional judgment.<br>References: <a href="https://professional.heart.org/en/science-news/2025-guideline-for-the-management-of-patients-with-acute-coronary-syndromes" target="_blank" rel="noopener">2025 ACS Guideline (AHA)</a> · <a href="https://nanda.org/" target="_blank" rel="noopener">NANDA International</a></div></footer>`}
function home(){return `<main class="shell"><section class="hero"><div><div class="eyebrow">Nursing knowledge, made clinical</div><h1>Study smarter.<br><span>Think like a nurse.</span></h1><p class="lead">Comprehensive nursing reviews, evidence-informed care plans, and clinical judgment cases—organized for university learning and NCLEX-style practice.</p><div class="actions"><button class="btn" onclick="go('topic')">Explore MI Review →</button><button class="btn secondary" onclick="go('courses')">Browse Courses</button></div><div class="chips"><span class="chip">11 review sections</span><span class="chip">NANDA-I care plans</span><span class="chip">Clinical cases</span><span class="chip">Mobile-friendly</span></div></div><div class="hero-art"><div class="eyebrow">Featured clinical review</div><div class="pulse">♡⌁</div><h2 style="font:800 28px Manrope;margin:0">Myocardial Infarction</h2><p style="color:var(--muted)">From coronary ischemia to nursing priorities and patient-specific care plans.</p><div class="mini"><strong>Clinical Judgment Pathway</strong><br><span style="color:var(--accent)">Recognize cues → Analyze → Prioritize → Act → Evaluate</span></div></div></section><section class="section"><div class="eyebrow">Explore the curriculum</div><h2>Adult Health Nursing I</h2><p class="sub">Five systems, one connected knowledge base. MI and Heart Failure have draft reviews; other topics are curriculum placeholders.</p><div class="grid">${Object.entries(systems).map(([name,items])=>`<div class="card"><div class="iconbox">${icons[name]}</div><h3>${name}</h3><p>${items.length} mapped topic headings</p><button class="btn secondary" onclick="go('system',{system:'${name}'})">Explore system →</button></div>`).join('')}</div></section><section class="section"><div class="eyebrow">How learning works</div><h2>Learn. Apply. Reflect.</h2><div class="grid"><div class="card"><div class="iconbox">▤</div><h3>Study Mode</h3><p>Organized sections, clinical pearls, diagnostics, and nursing rationales.</p></div><div class="card"><div class="iconbox">✚</div><h3>Nursing Care Plans</h3><p>Patient-specific assessment cues, candidate NANDA-I diagnoses, outcomes, and evaluation.</p></div><div class="card"><div class="iconbox">◎</div><h3>Practice Mode</h3><p>NCLEX-style questions with feedback after submission and case-based reasoning.</p></div></div></section></main>`}
function courses(){return `<main class="shell"><div class="pagehead"><div class="crumb">Course library</div><h1>Adult Health Nursing I</h1><p class="sub">Select a body system. Curriculum headings are mapped; MI and Heart Failure have developed draft learning content.</p></div><div class="grid">${Object.entries(systems).map(([name,items])=>`<div class="card"><div class="iconbox">${icons[name]}</div><h3>${name}</h3><p>${items.length} topic headings</p><button class="btn secondary" onclick="go('system',{system:'${name}'})">View topics →</button></div>`).join('')}</div></main>`}
function systemPage(){let arr=systems[state.system];return `<main class="shell"><div class="pagehead"><div class="crumb">Adult Health Nursing I / Systems</div><h1>${state.system}</h1><p class="sub">${arr.length} mapped headings · Content development in progress</p></div><div class="listitems">${arr.map(t=>`<div class="topicitem"><strong>${t}</strong>${t==='Myocardial Infarction'?`<button class="btn" onclick="go('topic')">Open review →</button>`:t==='Heart Failure'?`<button class="btn" onclick="go('hf',{hfSection:0})">Open review →</button>`:`<small>Planned · Not yet written</small>`}</div>`).join('')}</div></main>`}
function sidebar(){return `<aside class="sidebar"><h4>Quick navigation</h4>${names.map((n,i)=>`<button class="sidebtn ${state.section===i?'active':''}" onclick="state.section=${i};render();window.scrollTo({top:170,behavior:'smooth'})">${String(i+1).padStart(2,'0')} · ${n}</button>`).join('')}<button class="sidebtn" onclick="go('cases')">12 · Clinical Cases</button><button class="sidebtn" onclick="go('practice')">13 · Practice Questions</button></aside>`}
function topic(){state.mode="study";return `<main class="shell"><div class="pagehead"><div class="crumb">Adult Health Nursing I / Cardiovascular / Comprehensive Review</div><h1>Myocardial Infarction (MI)</h1><p class="sub">Comprehensive + Exam-Focused · 11 sections · NANDA-I care plans · Clinical cases</p><div class="actions"><button class="btn ${state.mode==='study'?'':'secondary'}" onclick="state.mode='study';render()">Study Mode</button><button class="btn secondary" onclick="go('practice')">NCLEX Practice →</button><button class="btn secondary" onclick="saved=!saved;persist();render()">${saved?'★ Saved':'☆ Save topic'}</button></div><div class="statrow"><span><b>${done.length}/11</b> sections marked complete</span><span><b>${scores.length}</b> submitted practice answers</span><span>Draft · Clinical review pending</span></div><div class="progress"><div style="width:${done.length/11*100}%"></div></div></div><div class="layout">${sidebar()}<div class="content fade">${state.mode==='practice'?practiceInner():`<article class="panel"><div class="sectionbar"><span class="number">SECTION ${String(state.section+1).padStart(2,'0')} / 11</span><span class="chip">Comprehensive Review</span></div><h2>${names[state.section]}</h2>${sections[state.section]}${state.section===0?`<div class="mini"><strong>Tap-to-translate terminology:</strong> <button class="term" onclick="state.term=!state.term;render()">Ischemia</button>${state.term?'<span class="termnote">نقص التروية الدموية</span>':''}</div>`:''}<div class="actions"><button class="btn secondary" onclick="toggleDone()">${done.includes(state.section)?'✓ Marked complete':'Mark section complete'}</button></div></article><div class="actions" style="justify-content:space-between"><button class="btn secondary" ${state.section===0?'disabled':''} onclick="state.section--;render();window.scrollTo({top:170,behavior:'smooth'})">← Previous</button><button class="btn" ${state.section===10?'disabled':''} onclick="state.section++;render();window.scrollTo({top:170,behavior:'smooth'})">Next section →</button></div><div class="panel"><h3>Apply what you learned</h3><p>Work through solved and independent cases to connect pathophysiology, assessment, and nursing diagnoses.</p><button class="btn secondary" onclick="go('cases')">Open Clinical Cases →</button></div>`}</div></div></main>`}
function toggleDone(){done=done.includes(state.section)?done.filter(i=>i!==state.section):[...done,state.section];persist();render()}
function practiceInner(){let q=questions[state.q];return `<article class="panel"><div class="sectionbar"><span class="number">PRACTICE ${state.q+1} / ${questions.length}</span><span class="chip">NCLEX-style · Not official exam items</span></div><h2>Clinical Judgment Practice</h2><div class="question"><strong>${q.q}</strong>${q.options.map((o,i)=>`<button class="option ${state.choice===i?'selected':''}" onclick="state.choice=${i};state.submitted=false;render()">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<button class="btn" ${state.choice===null?'disabled':''} onclick="submitAnswer()">Submit answer</button>${state.submitted?`<div class="answer ${state.choice===q.correct?'':'bad'}"><strong>${state.choice===q.correct?'✓ Correct':'Review: Correct answer '+String.fromCharCode(65+q.correct)}</strong><ul>${q.why.map((w,i)=>`<li><b>${String.fromCharCode(65+i)}:</b> ${w}</li>`).join('')}</ul></div>`:''}</div><div class="actions"><button class="btn secondary" onclick="state.q=(state.q+questions.length-1)%questions.length;resetQuestion();render()">← Previous</button><button class="btn" onclick="state.q=(state.q+1)%questions.length;resetQuestion();render()">Next question →</button></div></article>`}
function resetQuestion(){state.choice=null;state.submitted=false}function submitAnswer(){if(state.choice===null)return;state.submitted=true;scores.push({q:state.q,correct:state.choice===questions[state.q].correct});persist();render()}
function practice(){return `<main class="shell"><div class="pagehead"><div class="crumb">Practice / MI</div><h1>Clinical Judgment Practice</h1><p class="sub">Choose an answer, submit, then review every rationale.</p></div><div style="max-width:850px">${practiceInner()}</div></main>`}
function casesPage(){let c=cases[state.case];return `<main class="shell"><div class="pagehead"><div class="crumb">Clinical Cases / Myocardial Infarction</div><h1>Clinical Case Library</h1><p class="sub">Two guided examples and one independent case. Educational scenarios, not real patient records.</p></div><div class="layout"><aside class="sidebar"><h4>Choose a case</h4>${cases.map((c,i)=>`<button class="sidebtn ${state.case===i?'active':''}" onclick="state.case=${i};state.caseReveal=false;state.caseChoice=null;render()">${c.title}</button>`).join('')}</aside><article class="panel"><span class="number">${c.level.toUpperCase()}</span><h2>${c.title}</h2><h3>Patient chart</h3><p>${c.body}</p><h3>Clinical decision</h3><p>Identify the immediate priority, potential complications, and the nursing assessment cues that support your response.</p>${state.case===2&&!state.caseReveal?`<div class="question"><strong>Choose the safest initial response before revealing the rationale.</strong>${['Administer nitroglycerin despite hypotension','Activate STEMI response and assess for RV involvement','Wait for serial troponin before escalation','Administer routine high-flow oxygen at SpO₂ 95%'].map((o,i)=>`<button class="option ${state.caseChoice===i?'selected':''}" onclick="state.caseChoice=${i};render()">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<button class="btn" ${state.caseChoice===null?'disabled':''} onclick="state.caseReveal=true;render()">Submit and view rationales</button></div>`:`<div class="callout"><strong>Priority response:</strong> ${c.answer}</div><h3>Clinical rationale</h3><p>${c.why}</p>${state.case===2?`<h3>Option-by-option rationale</h3><ul><li><strong>A:</strong> Unsafe in hypotension and suspected RV infarction.</li><li><strong>B:</strong> Correct: time-critical STEMI pathway and focused RV assessment.</li><li><strong>C:</strong> Do not delay STEMI response for troponin.</li><li><strong>D:</strong> Routine oxygen is not indicated at SpO₂ 95% without another clinical reason.</li></ul><h3>Next assessment</h3><p>Request right-sided ECG leads where indicated, reassess perfusion and rhythm, and prepare for urgent reperfusion.</p>`:''}${state.case===2?'<button class="btn secondary" onclick="state.caseReveal=false;state.caseChoice=null;render()">Hide rationale</button>':''}`}<div class="callout warning"><strong>Case development note:</strong> Full multi-stage NGN item sets and formal NANDA-I coding are planned for the clinically reviewed release.</div></article></div></main>`}
function searchResults(){if(state.page==='search')render()}
function searchPage(){const q=state.search.toLowerCase().trim();let results=Object.entries(systems).flatMap(([sys,items])=>items.filter(x=>x.toLowerCase().includes(q)).map(x=>({sys,title:x})));return `<main class="shell"><div class="pagehead"><div class="crumb">Search</div><h1>Find a nursing topic</h1><p class="sub">${q?`${results.length} matching headings for “${escapeHtml(state.search)}”`:'Type a topic in the search field above.'}</p></div><div class="listitems">${q?results.map(x=>`<div class="topicitem"><div><strong>${x.title}</strong><br><small>${x.sys} · Adult Health Nursing I</small></div>${x.title==='Myocardial Infarction'?`<button class="btn" onclick="go('topic')">Open review</button>`:x.title==='Heart Failure'?`<button class="btn" onclick="go('hf',{hfSection:0})">Open review</button>`:'<small>Planned</small>'}</div>`).join('')||'<div class="empty">No matching topics found.</div>':'<div class="empty">Search by condition, body system, or keyword.</div>'}</div></main>`}
function render(){let body={home,courses,system:systemPage,topic,hf:heartFailurePage,practice,cases:casesPage,search:searchPage}[state.page]||home;document.getElementById('app').innerHTML=header()+body()+footer();document.title=(state.page==='topic'?'Myocardial Infarction | ':state.page==='home'?'':'Nursing Atlas | ')+'Nursing Atlas'}
window.go=go;window.state=state;window.render=render;window.toggleDone=toggleDone;window.submitAnswer=submitAnswer;window.resetQuestion=resetQuestion;window.searchResults=searchResults;render();


// Optional, selection-based English → Arabic translation. No automatic translation.
// Uses the user's chosen selection and opens a translation page in a new tab;
// no translation API key, server, or account is required.
(function setupSelectionTranslation(){
  const bar=document.createElement('div');
  bar.id='selection-translate';
  bar.setAttribute('role','group');
  bar.setAttribute('aria-label','Selected text translation');
  bar.hidden=true;
  bar.innerHTML='<span id="selected-phrase"></span><button type="button" id="translate-selected" aria-label="Translate selected text to Arabic">🌐 Translate to Arabic ↗</button><button type="button" id="dismiss-translation" aria-label="Close translation option">×</button>';
  document.body.appendChild(bar);
  let selected='';
  const hide=()=>{bar.hidden=true};
  function update(){
    const selection=window.getSelection();
    const value=selection?selection.toString().trim():'';
    if(!value||value.length>400||selection.isCollapsed){hide();return}
    const node=selection.anchorNode;
    const element=node?.nodeType===1?node:node?.parentElement;
    if(!element||!element.closest('#app')||element.closest('input,textarea,button')){hide();return}
    selected=value;
    document.getElementById('selected-phrase').textContent=value.length>42?value.slice(0,42)+'…':value;
    bar.hidden=false;
  }
  document.addEventListener('selectionchange',()=>{if(!bar.hidden)update()});
  document.addEventListener('touchend',()=>setTimeout(update,350),{passive:true});
  document.addEventListener('mouseup',()=>setTimeout(update,50));
  document.getElementById('translate-selected').addEventListener('click',()=>{
    if(!selected)return;
    const url='https://translate.google.com/?sl=en&tl=ar&text='+encodeURIComponent(selected)+'&op=translate';
    window.open(url,'_blank','noopener,noreferrer');
    hide();
  });
  document.getElementById('dismiss-translation').addEventListener('click',hide);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});
})();
